                        else if (typeof(Thing).IsAssignableFrom(pt))
                        {
                            // STATIC_CALL_WIDEN_PAWNS_NEED_NOT_APPLY: a Thing/Pawn arg by ThingID or thingIDNumber
                            if (a.Length == 0 || a == "null") { vals[i] = null; }
                            else
